      <CommandPalette
        items={paletteItems}
        open={palette !== null}
        onOpenChange={(o) => !o && setPalette(null)}
        hotkey={false}
        placeholder={palette === "files" ? "Search files by name" : "Run a command"}
        emptyMessage={palette === "files" ? "No files match." : "No commands match."}
