export type PanelTab = "problems" | "output" | "terminal"
export type OutputLine = { time: number; text: string; level?: "info" | "error" }

const SEVERITY = {
  error: { icon: <XCircleIcon />, className: "text-destructive" },
  warning: { icon: <WarningIcon />, className: "text-warning" },
  info: { icon: <InfoIcon />, className: "text-primary" },
} as const

/* -------------------------------- terminals ------------------------------- */

function TerminalArea({ terms, visible, compact }: { terms: Terminals; visible: boolean; compact: boolean }) {
  const handles = React.useRef(new Map<string, TerminalHandle>())
  const { sessions, activeGroup, active } = terms

  // Focus the active terminal when it changes or the area shows.
  React.useEffect(() => {
    if (!visible || !active) return
    const id = requestAnimationFrame(() => {
      const h = handles.current.get(active)
      h?.fit()
      h?.focus()
    })
    return () => cancelAnimationFrame(id)
  }, [visible, active])

  if (!sessions.length)
    return (
      <div className={cn("flex h-full flex-col items-center justify-center gap-2 p-6 text-center", !visible && "hidden")}>
        <p className="text-ui text-muted-foreground">No terminal running.</p>
        <button
          type="button"
          onClick={() => terms.create()}
          className="text-ui text-primary outline-none hover:underline focus-visible:ring-2 focus-visible:ring-ring/50"
        >
          New terminal
        </button>
      </div>
    )

  const showList = !compact && (sessions.length > 1 || activeGroup.length > 1)
  const anySplit = terms.groups.some((g) => g.length > 1)
  return (
    <div className={cn("flex h-full min-h-0", !visible && "hidden")}>
      <div className="flex min-w-0 flex-1">
        {sessions.map((s) => {
          const shown = activeGroup.includes(s.id)
          const index = activeGroup.indexOf(s.id)
          return (
            <div
              key={s.id}
              onMouseDown={() => terms.setActive(s.id)}
              className={cn("relative min-w-0 flex-1 pt-1 pl-3", !shown && "hidden", index > 0 && "border-l border-border")}
            >
              <Terminal
                ref={(h) => {
                  if (h) handles.current.set(s.id, h)
                  else handles.current.delete(s.id)
                }}
                transport={s.transport}
                fontSize={12}
                className="h-full"
              />
            </div>
          )
        })}
      </div>
      {showList && (
        <ScrollArea className="w-40 shrink-0 border-l border-border">
        <ul aria-label="Terminals" className="flex flex-col gap-px p-1">
          {terms.groups.map((g) =>
            g.map((id, i) => {
              const s = sessions.find((x) => x.id === id)!
              const selected = id === active
              return (
                <li key={id} className="group/term flex h-6 items-center gap-1 rounded-sm pr-0.5 pl-1.5 text-ui-sm hover:bg-secondary data-selected:bg-foreground/6" data-selected={selected || undefined}>
                  <button
                    type="button"
                    onClick={() => terms.setActive(id)}
                    aria-current={selected || undefined}
                    className={cn("flex min-w-0 flex-1 items-center gap-1.5 text-start outline-none focus-visible:underline", selected ? "text-foreground" : "text-muted-foreground")}
                  >
                    {anySplit && <span aria-hidden className="w-2 shrink-0 font-mono text-ui-xs text-muted-foreground">{g.length < 2 ? "" : i === g.length - 1 ? "└" : i === 0 ? "┌" : "├"}</span>}
                    <TerminalSquareIcon className="size-3.5 shrink-0" />
                    <span className="truncate">{s.title}</span>
                  </button>
                  <button
                    type="button"
                    aria-label={`Kill ${s.title}`}
                    onClick={() => terms.kill(id)}
                    className="relative flex size-5 shrink-0 items-center justify-center rounded-sm text-muted-foreground opacity-0 after:absolute after:-inset-0.5 outline-none group-hover/term:opacity-100 hover:bg-foreground/8 hover:text-foreground focus-visible:opacity-100 focus-visible:ring-2 focus-visible:ring-ring/50"
                  >
                    <TrashIcon className="size-3" />
                  </button>
                </li>
              )
            })
          )}
        </ul>
        </ScrollArea>
      )}
    </div>
  )
}

/* -------------------------------- problems -------------------------------- */

function ProblemsList({ problems, onOpen }: { problems: Problem[]; onOpen: (p: Problem) => void }) {
  const byFile = React.useMemo(() => {
    const map = new Map<string, Problem[]>()
    for (const p of problems) map.set(p.path, [...(map.get(p.path) ?? []), p])
    return [...map]
  }, [problems])
  if (!problems.length) return <p className="px-4 py-3 text-ui text-muted-foreground">No problems in the workspace.</p>
  return (
    <ScrollArea className="h-full" viewportClassName="px-2 py-1">
      <ul aria-label="Problems" className="flex flex-col">
        {byFile.map(([path, list]) => {
          const kind = getFileKind(basename(path))
          return (
            <li key={path}>
              <div className="flex h-6 items-center gap-1.5 px-1 text-ui">
                <span className={cn("flex size-4 shrink-0 items-center justify-center", kind.className)}>{kind.icon}</span>
                <span className="truncate">{basename(path)}</span>
                <span className="min-w-0 truncate text-ui-xs text-muted-foreground">{rel(dirname(path))}</span>
                <span className="rounded-full bg-secondary px-1.5 text-ui-xs text-muted-foreground tabular-nums">{list.length}</span>
              </div>
              <ul>
                {list.map((p, i) => (
                  <li key={i}>
                    <button
                      type="button"
                      onClick={() => onOpen(p)}
                      className="flex min-h-6 w-full items-center gap-2 rounded-sm py-0.5 pr-2 pl-7 text-start text-ui outline-none hover:bg-secondary focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-inset"
                    >
                      <span className={cn("flex size-4 shrink-0 items-center justify-center [&_svg]:size-3.5", SEVERITY[p.severity].className)}>{SEVERITY[p.severity].icon}</span>
                      <span className="min-w-0 flex-1 truncate">{p.message}</span>
                      {p.source && <span className="shrink-0 text-ui-xs text-muted-foreground">{p.source}</span>}
                      <span className="shrink-0 text-ui-xs text-muted-foreground tabular-nums">
                        Ln {p.line}, Col {p.column}
                      </span>
                    </button>
                  </li>
                ))}
              </ul>
            </li>
          )
        })}
      </ul>
    </ScrollArea>
  )
}

/* --------------------------------- output --------------------------------- */

function OutputLog({ lines }: { lines: OutputLine[] }) {
  const ref = React.useRef<HTMLDivElement>(null)
  React.useEffect(() => {
    const el = ref.current
    if (el) el.scrollTop = el.scrollHeight
  }, [lines.length])
  return (
    <ScrollArea className="h-full" viewportRef={ref} viewportClassName="px-4 py-2">
      <ol aria-label="Output" className="font-mono text-ui-sm leading-5">
        {lines.map((l, i) => (
          <li key={i} className={cn("whitespace-pre-wrap", l.level === "error" ? "text-destructive" : "text-foreground")}>
            <span className="text-muted-foreground tabular-nums">[{new Date(l.time).toLocaleTimeString([], { hour12: false })}]</span> {l.text}
          </li>
        ))}
      </ol>
    </ScrollArea>
  )
}

/* ---------------------------------- panel --------------------------------- */

/**
 * The bottom panel: Problems, Output and Terminal tabs. Terminals stay mounted
 * while another tab shows, so their screens and shells keep their state.
 */
export function BottomPanel({
  tab,
  onTabChange,
  terms,
  problems,
  output,
  onOpenProblem,
  onClose,
  maximized,
  onToggleMaximize,
  compact = false,
}: {
  tab: PanelTab
  onTabChange: (tab: PanelTab) => void
  terms: Terminals
  problems: Problem[]
  output: OutputLine[]
  onOpenProblem: (p: Problem) => void
  onClose: () => void
  maximized?: boolean
  onToggleMaximize?: () => void
  /** Phone layout (in a bottom sheet): no terminal list or split. */
  compact?: boolean
}) {
  const errors = problems.filter((p) => p.severity === "error").length
  const warnings = problems.filter((p) => p.severity === "warning").length
  return (
    <div className="flex h-full min-h-0 flex-col">
      <div className="flex h-9 shrink-0 items-center gap-1 px-2">
        <TabStrip variant="pill" value={tab} onValueChange={(v) => onTabChange(v as PanelTab)} aria-label="Panel" className="min-w-0 flex-1">
          <TabStripItem value="problems" icon={<AlertCircleIcon />} hint={false}>
            <span className="flex items-center gap-1.5">
              Problems
              {problems.length > 0 && <span className="rounded-full bg-secondary px-1.5 text-ui-xs tabular-nums">{errors + warnings || problems.length}</span>}
            </span>
          </TabStripItem>
          <TabStripItem value="output" icon={<InfoIcon />} hint={false}>
            Output
          </TabStripItem>
          <TabStripItem value="terminal" icon={<TerminalSquareIcon />} hint={false}>
            Terminal
          </TabStripItem>
        </TabStrip>
        {tab === "terminal" && (
          <>
            <IconAction label="New terminal" shortcut="⌃⇧`" size="icon-sm" onClick={() => terms.create()}>
              <PlusIcon />
            </IconAction>
            {!compact && (
              <IconAction label="Split terminal" size="icon-sm" onClick={() => terms.split()} disabled={!terms.sessions.length}>
                <Columns2Icon />
              </IconAction>
            )}
            <IconAction label="Kill terminal" size="icon-sm" onClick={() => terms.active && terms.kill(terms.active)} disabled={!terms.active}>
              <TrashIcon />
            </IconAction>
          </>
        )}
        {onToggleMaximize && (
          <IconAction label={maximized ? "Restore panel size" : "Maximize panel"} size="icon-sm" onClick={onToggleMaximize}>
            {maximized ? <ChevronDownIcon /> : <ChevronUpIcon />}
          </IconAction>
        )}
        <IconAction label="Close panel" shortcut="⌃`" size="icon-sm" onClick={onClose}>
          <XIcon />
        </IconAction>
      </div>
      <div className="min-h-0 flex-1">
        <TerminalArea terms={terms} visible={tab === "terminal"} compact={compact} />
        {tab === "problems" && <ProblemsList problems={problems} onOpen={onOpenProblem} />}
        {tab === "output" && <OutputLog lines={output} />}
      </div>
    </div>
  )
}

import type { TerminalTransport } from "@/registry/base-nova/ui/terminal"

/** A folder read from disk. Paths are relative to its root, `/`-separated. */
export type HostFolder = {
  name: string
  files: Record<string, string>
  dirs: string[]
  /** Files left out (too large, binary, or past the file limit). */
  skipped: number
}

/** Writes to the open folder. Paths are relative to its root. */
export interface HostFs {
  writeFile(path: string, content: string): Promise<void>
  mkdir(path: string): Promise<void>
  rm(path: string): Promise<void>
  rename(from: string, to: string): Promise<void>
}

/** A change made on disk by something else (another editor, a build, git). */
export type HostChange = { type: "write"; path: string; content: string } | { type: "mkdir"; path: string } | { type: "rm"; path: string }

/** Commands a native menu can send. */
export type HostCommand =
  | "open-folder"
  | "close-folder"
  | "save"
  | "save-all"
  | "new-file"
  | "new-folder"
  | "commands"
  | "files"
  | "toggle-sidebar"
  | "toggle-panel"
  | "new-terminal"

/**
 * What a desktop shell gives the editor. Every member is optional; without a
 * host the editor runs on its in-browser workspace.
 */
export interface VsCodeHost {
  /** Ask for a folder; resolves null when cancelled. */
  openFolder?: () => Promise<HostFolder | null>
  /** Stop working on the open folder. */
  closeFolder?: () => Promise<void> | void
  /** Required with `openFolder`. */
  fs?: HostFs
  /** Changes on disk while a folder is open. Returns an unsubscribe function. */
  onChanges?: (cb: (changes: HostChange[]) => void) => () => void
  /** A real shell for each new terminal. `cwd` is relative to the open folder; null when none is open. */
  terminal?: (opts: { cwd: string | null; folder: boolean }) => TerminalTransport
  /** Shell name shown in terminal titles. */
  shellName?: string
  onCommand?: (cb: (command: HostCommand) => void) => () => void
  /** Draw a title bar that drags the window, with room for the window controls on one side. */
  titleBar?: { controls: "left" | "right" | "none" }
}

"use client";

import * as React from "react"
import Editor, { loader, type Monaco, type OnMount } from "@monaco-editor/react"

import { Button } from "@/registry/base-nova/ui/button"
import { Loader } from "@/registry/base-nova/ui/loader"

import type { Docs } from "./buffers"
import { applyEditorTheme, EDITOR_THEME, monoFont, TYPE_SHIMS } from "./editor-theme"
import { languageOf } from "./languages"
import { basename, inWorkspace, type Workspace } from "./workspace"

type CodeEditorInstance = Parameters<OnMount>[0]

export type Problem = {
  path: string
  line: number
  column: number
  endLine: number
  endColumn: number
  message: string
  severity: "error" | "warning" | "info"
  source?: string
}

export type CodeEditorHandle = {
  /** Show a file at a position and select the range. */
  reveal: (line: number, column: number, endLine?: number, endColumn?: number) => void
  focus: () => void
  /** Run a built-in editor action (`editor.action.formatDocument`, `editor.action.gotoLine`…). */
  run: (actionId: string) => void
}

const uriOf = (monaco: Monaco, path: string) => monaco.Uri.file(path)

let configured = false

/** Compiler settings and module shims for the TypeScript worker, once per page. */
function configure(monaco: Monaco) {
  if (configured) return
  configured = true
  const ts = monaco.typescript ?? monaco.languages.typescript
  if (!ts) return
  const options = {
    target: ts.ScriptTarget.ES2022 ?? ts.ScriptTarget.ESNext,
    module: ts.ModuleKind.ESNext,
    moduleResolution: ts.ModuleResolutionKind.NodeJs,
    jsx: ts.JsxEmit.ReactJSX,
    strict: true,
    esModuleInterop: true,
    allowSyntheticDefaultImports: true,
    allowNonTsExtensions: true,
    skipLibCheck: true,
    isolatedModules: true,
  }
  ts.typescriptDefaults.setCompilerOptions(options)
  ts.javascriptDefaults.setCompilerOptions({ ...options, allowJs: true, checkJs: false })
  ts.typescriptDefaults.setEagerModelSync(true)
  ts.typescriptDefaults.addExtraLib(TYPE_SHIMS, "file:///node_modules/@types/workspace-shims/index.d.ts")
}

/**
 * The code editor: one editor instance whose model switches with the active
 * tab. Every workspace file has a model, so imports resolve across files and
 * the Problems list covers the whole workspace. Typing writes to the buffer
 * store; buffer changes from elsewhere (revert, a terminal write) flow back in.
 * While the editor loads it shows a spinner; if it cannot load it falls back
 * to a plain text area on the same buffers.
 */
export function CodeEditor({
  ws,
  docs,
  path,
  onCursor,
  onProblems,
  onSave,
  compact = false,
  handleRef,
}: {
  ws: Workspace
  docs: Docs
  path: string | null
  onCursor: (pos: { line: number; column: number; selected: number }) => void
  onProblems: (problems: Problem[]) => void
  onSave: () => void
  /** Phone layout: no minimap, narrower gutter. */
  compact?: boolean
  handleRef?: React.Ref<CodeEditorHandle>
}) {
  const [monaco, setMonaco] = React.useState<Monaco | null>(null)
  const [editor, setEditor] = React.useState<CodeEditorInstance | null>(null)
  const [failed, setFailed] = React.useState(false)
  const viewStates = React.useRef(new Map<string, unknown>())
  const current = React.useRef<string | null>(null)
  const syncing = React.useRef(false)
  const wsVersion = React.useSyncExternalStore((cb) => ws.subscribe(cb), ws.getVersion, ws.getVersion)
  const docsVersion = React.useSyncExternalStore((cb) => docs.subscribe(cb), docs.getVersion, docs.getVersion)

  const latest = React.useRef({ onCursor, onProblems, onSave })
  latest.current = { onCursor, onProblems, onSave }

  // Give up on the editor (blocked network, offline) after a while and use the text area.
  React.useEffect(() => {
    let live = true
    const timer = setTimeout(() => live && !monaco && setFailed(true), 20000)
    loader.init().then(
      () => clearTimeout(timer),
      () => live && setFailed(true)
    )
    return () => {
      live = false
      clearTimeout(timer)
    }
  }, [monaco])

  /* -------------------------- models follow files -------------------------- */

  React.useEffect(() => {
    if (!monaco) return
    syncing.current = true
    const wanted = new Set([...ws.listFiles(), ...docs.paths()])
    for (const p of wanted) {
      const text = docs.get(p) ?? (ws.exists(p) && !ws.isDir(p) ? ws.readFile(p) : "")
      const uri = uriOf(monaco, p)
      const model = monaco.editor.getModel(uri)
      if (!model) {
        const created = monaco.editor.createModel(text, languageOf(basename(p)).id, uri)
        created.onDidChangeContent(() => {
          if (!syncing.current) docs.set(p, created.getValue())
        })
      } else if (model.getValue() !== text) {
        // Keep it undoable: one edit that replaces the whole text.
        model.pushEditOperations([], [{ range: model.getFullModelRange(), text }], () => null)
      }
    }
    for (const model of monaco.editor.getModels()) {
      const p = model.uri.path
      if (model.uri.scheme === "file" && inWorkspace(p) && !wanted.has(p) && model !== editor?.getModel()) model.dispose()
    }
    syncing.current = false
  }, [monaco, editor, ws, docs, wsVersion, docsVersion])

  /* ------------------------------ active model ----------------------------- */

  React.useEffect(() => {
    if (!monaco || !editor) return
    const prev = current.current
    if (prev === path) return
    if (prev) viewStates.current.set(prev, editor.saveViewState())
    current.current = path
    const model = path ? monaco.editor.getModel(uriOf(monaco, path)) : null
    editor.setModel(model)
    if (path && model) {
      const state = viewStates.current.get(path)
      if (state) editor.restoreViewState(state as Parameters<CodeEditorInstance["restoreViewState"]>[0])
      const pos = editor.getPosition()
      if (pos) latest.current.onCursor({ line: pos.lineNumber, column: pos.column, selected: 0 })
    }
  }, [monaco, editor, path, wsVersion])

  /* ---------------------------- theme and markers --------------------------- */

  React.useEffect(() => {
    if (!monaco) return
    const html = document.documentElement
    const obs = new MutationObserver(() => applyEditorTheme(monaco))
    obs.observe(html, { attributes: true, attributeFilter: ["class", "data-accent", "style"] })
    const collect = () => {
      const problems: Problem[] = []
      for (const m of monaco.editor.getModelMarkers({})) {
        if (m.resource.scheme !== "file" || !inWorkspace(m.resource.path)) continue
        problems.push({
          path: m.resource.path,
          line: m.startLineNumber,
          column: m.startColumn,
          endLine: m.endLineNumber,
          endColumn: m.endColumn,
          message: typeof m.message === "string" ? m.message : String(m.message),
          severity: m.severity >= 8 ? "error" : m.severity >= 4 ? "warning" : "info",
          source: m.source,
        })
      }
      problems.sort((a, b) => a.path.localeCompare(b.path) || a.line - b.line)
      latest.current.onProblems(problems)
    }
    const sub = monaco.editor.onDidChangeMarkers(collect)
    collect()
    return () => {
      obs.disconnect()
      sub.dispose()
    }
  }, [monaco])

  React.useEffect(() => {
    editor?.updateOptions({ minimap: { enabled: !compact }, lineNumbersMinChars: compact ? 3 : 4, folding: !compact })
  }, [editor, compact])

  React.useImperativeHandle(
    handleRef,
    () => ({
      reveal: (line, column, endLine = line, endColumn = column) => {
        if (!editor) return
        editor.setSelection({ startLineNumber: line, startColumn: column, endLineNumber: endLine, endColumn })
        editor.revealRangeInCenterIfOutsideViewport({ startLineNumber: line, startColumn: column, endLineNumber: endLine, endColumn })
        editor.focus()
      },
      focus: () => editor?.focus(),
      run: (id) => {
        editor?.focus()
        void editor?.getAction(id)?.run()
      },
    }),
    [editor]
  )

  if (failed && !monaco) return <FallbackEditor docs={docs} path={path} onSave={onSave} />

  return (
    <div className="relative h-full min-h-0">
      {!path && <EmptyEditor />}
      <div className={path ? "h-full" : "invisible h-full"}>
        <Editor
          theme={EDITOR_THEME}
          keepCurrentModel
          loading={<EditorLoading />}
          beforeMount={(m) => {
            configure(m)
            applyEditorTheme(m)
          }}
          onMount={(ed, m) => {
            ed.onDidChangeCursorSelection((e) => {
              const model = ed.getModel()
              const sel = e.selection
              latest.current.onCursor({
                line: sel.positionLineNumber,
                column: sel.positionColumn,
                selected: model ? model.getValueInRange(sel).length : 0,
              })
            })
            // Inside the editor its own key handling runs first, so bind save here too.
            ed.addCommand(m.KeyMod.CtrlCmd | m.KeyCode.KeyS, () => latest.current.onSave())
            setEditor(ed)
            setMonaco(m)
          }}
          options={{
            fontFamily: typeof window === "undefined" ? undefined : monoFont(),
            fontSize: 12.5,
            lineHeight: 20,
            fontLigatures: true,
            automaticLayout: true,
            minimap: { enabled: !compact, renderCharacters: false, scale: 1, maxColumn: 80 },
            scrollBeyondLastLine: false,
            padding: { top: 8, bottom: 8 },
            renderLineHighlight: "line",
            smoothScrolling: true,
            cursorBlinking: "smooth",
            bracketPairColorization: { enabled: true },
            guides: { indentation: true, bracketPairs: false },
            tabSize: 2,
            stickyScroll: { enabled: true },
            overviewRulerBorder: false,
            scrollbar: { verticalScrollbarSize: 10, horizontalScrollbarSize: 10, useShadows: false },
            fixedOverflowWidgets: true,
          }}
        />
      </div>
    </div>
  )
}

function EditorLoading() {
  return (
    <div className="flex h-full items-center justify-center gap-2 text-ui text-muted-foreground">
      <Loader size="sm" />
      Loading editor…
    </div>
  )
}

function EmptyEditor() {
  return (
    <div className="absolute inset-0 z-10 flex flex-col items-center justify-center gap-3 bg-background p-6 text-center">
      <p className="text-ui text-muted-foreground">No file open.</p>
      <dl className="grid grid-cols-2 gap-x-4 gap-y-1.5 text-ui-sm text-muted-foreground">
        <dt className="text-end">Show all commands</dt>
        <dd className="text-start font-mono">⇧⌘P</dd>
        <dt className="text-end">Go to file</dt>
        <dd className="text-start font-mono">⌘P</dd>
        <dt className="text-end">Toggle panel</dt>
        <dd className="text-start font-mono">⌃`</dd>
      </dl>
    </div>
  )
}

/** Plain text area on the same buffers, for when the editor cannot load. */
function FallbackEditor({ docs, path, onSave }: { docs: Docs; path: string | null; onSave: () => void }) {
  React.useSyncExternalStore((cb) => docs.subscribe(cb), docs.getVersion, docs.getVersion)
  if (!path) return <EmptyEditor />
  return (
    <div className="flex h-full flex-col">
      <div className="flex h-8 shrink-0 items-center gap-2 border-b border-warning-border bg-warning-subtle px-3 text-ui-sm text-muted-foreground">
        <span className="min-w-0 flex-1 truncate">The editor could not load. Editing as plain text.</span>
        <Button variant="ghost" size="xs" onClick={() => window.location.reload()}>
          Retry
        </Button>
      </div>
      <textarea
        aria-label={`Contents of ${basename(path)}`}
        spellCheck={false}
        value={docs.get(path) ?? ""}
        onChange={(e) => docs.set(path, e.target.value)}
        onKeyDown={(e) => {
          if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "s") {
            e.preventDefault()
            onSave()
          }
        }}
        className="min-h-0 flex-1 resize-none bg-background p-3 font-mono text-ui-sm leading-5 text-foreground outline-none"
      />
    </div>
  )
}

import type { Workspace } from "./workspace"

/**
 * Open editor buffers (path → text), next to the saved files in the workspace.
 * A buffer is dirty while it differs from the file on disk. When the file
 * changes on disk (a terminal command) and its buffer is clean, the buffer
 * follows it.
 */
export class Docs {
  private buffers = new Map<string, string>()
  private disk = new Map<string, string | undefined>()
  private listeners = new Set<() => void>()
  version = 0

  constructor(private ws: Workspace) {}

  private read(path: string) {
    return this.ws.exists(path) && !this.ws.isDir(path) ? this.ws.readFile(path) : undefined
  }

  subscribe(cb: () => void) {
    this.listeners.add(cb)
    return () => {
      this.listeners.delete(cb)
    }
  }

  getVersion = () => this.version

  private changed() {
    this.version++
    this.listeners.forEach((l) => l())
  }

  has(path: string) {
    return this.buffers.has(path)
  }

  get(path: string) {
    return this.buffers.get(path)
  }

  paths() {
    return [...this.buffers.keys()]
  }

  /** Open a buffer on the file's current content (no-op if it is open). */
  open(path: string) {
    if (this.buffers.has(path)) return
    const content = this.read(path) ?? ""
    this.buffers.set(path, content)
    this.disk.set(path, content)
    this.changed()
  }

  close(path: string) {
    if (!this.buffers.delete(path)) return
    this.disk.delete(path)
    this.changed()
  }

  set(path: string, text: string) {
    if (this.buffers.get(path) === text) return
    this.buffers.set(path, text)
    this.changed()
  }

  isDirty(path: string) {
    const text = this.buffers.get(path)
    return text !== undefined && text !== this.read(path)
  }

  dirtyPaths() {
    return this.paths().filter((p) => this.isDirty(p))
  }

  /** Write the buffer to disk. */
  save(path: string) {
    const text = this.buffers.get(path)
    if (text === undefined) return false
    this.ws.writeFile(path, text)
    this.disk.set(path, text)
    this.changed()
    return true
  }

  /** Throw away unsaved edits. */
  revert(path: string) {
    const content = this.read(path)
    if (content === undefined) return
    this.buffers.set(path, content)
    this.disk.set(path, content)
    this.changed()
  }

  /** Follow a rename on disk (a file, or every buffer inside a folder). */
  move(from: string, to: string) {
    for (const p of this.paths()) {
      if (p !== from && !p.startsWith(`${from}/`)) continue
      const next = to + p.slice(from.length)
      this.buffers.set(next, this.buffers.get(p)!)
      this.disk.set(next, this.disk.get(p))
      this.buffers.delete(p)
      this.disk.delete(p)
    }
    this.changed()
  }

  /**
   * Reconcile with disk after the workspace changed. Clean buffers take the new
   * content. Returns the paths whose file disappeared, so their tabs can close
   * (dirty ones stay open; saving brings the file back).
   */
  sync(): string[] {
    const gone: string[] = []
    let touched = false
    for (const [p, text] of this.buffers) {
      const now = this.read(p)
      const before = this.disk.get(p)
      if (now === before) continue
      if (now === undefined) {
        if (text === before) gone.push(p)
      } else if (text === before) {
        this.buffers.set(p, now)
        touched = true
      }
      this.disk.set(p, now)
    }
    if (touched) this.changed()
    return gone
  }

  clear() {
    this.buffers.clear()
    this.disk.clear()
    this.changed()
  }
}

import type { Monaco } from "@monaco-editor/react"

let ctx: CanvasRenderingContext2D | null = null

/**
 * A theme token (`--background`, `--primary`…) as `#rrggbbaa`, the only colour
 * format the editor accepts. The browser resolves any CSS colour (oklch,
 * var() chains, alpha) by painting one pixel.
 */
function token(name: string, alpha = 1) {
  const value = getComputedStyle(document.documentElement).getPropertyValue(name).trim()
  if (!ctx) {
    const canvas = document.createElement("canvas")
    canvas.width = canvas.height = 1
    ctx = canvas.getContext("2d", { willReadFrequently: true })
  }
  if (!ctx || !value) return "#00000000"
  ctx.clearRect(0, 0, 1, 1)
  ctx.fillStyle = "#000"
  ctx.fillStyle = value
  ctx.fillRect(0, 0, 1, 1)
  const [r, g, b, a] = ctx.getImageData(0, 0, 1, 1).data
  const hex = (n: number) => Math.round(n).toString(16).padStart(2, "0")
  return `#${hex(r)}${hex(g)}${hex(b)}${hex(a * alpha)}`
}

export const EDITOR_THEME = "workspace-tokens"

export function isDark() {
  return document.documentElement.classList.contains("dark")
}

/** Define (or redefine) the editor theme from the current CSS tokens and apply it. */
export function applyEditorTheme(monaco: Monaco) {
  const dark = isDark()
  const fg = (a: number) => token("--foreground", a)
  const primary = (a: number) => token("--primary", a)
  const muted = token("--muted-foreground")
  monaco.editor.defineTheme(EDITOR_THEME, {
    base: dark ? "vs-dark" : "vs",
    inherit: true,
    rules: [{ token: "comment", foreground: muted.slice(1, 7), fontStyle: "italic" }],
    colors: {
      "editor.background": token("--background"),
      "editor.foreground": token("--foreground"),
      "editorGutter.background": token("--background"),
      "minimap.background": token("--background"),
      "editorLineNumber.foreground": token("--muted-foreground", 0.7),
      "editorLineNumber.activeForeground": token("--foreground"),
      "editorCursor.foreground": primary(1),
      "editor.selectionBackground": primary(dark ? 0.35 : 0.2),
      "editor.inactiveSelectionBackground": primary(dark ? 0.2 : 0.12),
      "editor.selectionHighlightBackground": primary(0.12),
      "editor.wordHighlightBackground": fg(0.06),
      "editor.findMatchBackground": token("--warning", 0.45),
      "editor.findMatchHighlightBackground": token("--warning", 0.22),
      "editor.lineHighlightBackground": fg(dark ? 0.04 : 0.03),
      "editor.lineHighlightBorder": "#00000000",
      "editorIndentGuide.background1": token("--border"),
      "editorIndentGuide.activeBackground1": fg(0.24),
      "editorWhitespace.foreground": fg(0.18),
      "editorBracketMatch.background": primary(0.12),
      "editorBracketMatch.border": primary(0.5),
      "editorError.foreground": token("--destructive"),
      "editorWarning.foreground": token("--warning"),
      "editorInfo.foreground": primary(1),
      "editorOverviewRuler.border": "#00000000",
      "editorStickyScroll.background": token("--background"),
      "editorStickyScroll.shadow": fg(0.08),
      "editorWidget.background": token("--popover"),
      "editorWidget.foreground": token("--popover-foreground"),
      "editorWidget.border": token("--border"),
      "editorHoverWidget.background": token("--popover"),
      "editorHoverWidget.border": token("--border"),
      "editorSuggestWidget.background": token("--popover"),
      "editorSuggestWidget.border": token("--border"),
      "editorSuggestWidget.selectedBackground": fg(0.06),
      "editorSuggestWidget.highlightForeground": primary(1),
      "list.hoverBackground": fg(0.04),
      "list.activeSelectionBackground": fg(0.06),
      "list.activeSelectionForeground": token("--foreground"),
      "list.highlightForeground": primary(1),
      "input.background": token("--card"),
      "input.border": token("--input"),
      "focusBorder": token("--ring", 0.6),
      "scrollbarSlider.background": fg(0.1),
      "scrollbarSlider.hoverBackground": fg(0.18),
      "scrollbarSlider.activeBackground": fg(0.26),
      "scrollbar.shadow": "#00000000",
      "widget.shadow": "#00000014",
    },
  })
  monaco.editor.setTheme(EDITOR_THEME)
}

/** The mono font stack from the theme. */
export function monoFont() {
  return getComputedStyle(document.documentElement).getPropertyValue("--font-mono").trim() || "monospace"
}

/** Loose module shims, so the starter project type-checks without node_modules. */
export const TYPE_SHIMS = `
declare module "react" {
  export type ReactNode = any
  export type SetStateAction<T> = T | ((prev: T) => T)
  export function useState<T>(init: T | (() => T)): [T, (value: SetStateAction<T>) => void]
  export function useEffect(effect: () => void | (() => void), deps?: readonly unknown[]): void
  export function useMemo<T>(factory: () => T, deps: readonly unknown[]): T
  export function useCallback<T extends (...args: any[]) => any>(fn: T, deps: readonly unknown[]): T
  export function useRef<T>(init: T): { current: T }
  export const StrictMode: (props: { children?: ReactNode }) => any
  export const Fragment: any
}
declare module "react/jsx-runtime" {
  export const jsx: any
  export const jsxs: any
  export const Fragment: any
}
declare module "react-dom/client" {
  export function createRoot(el: Element): { render(node: any): void; unmount(): void }
}
declare module "node:assert/strict" {
  const assert: { equal(a: unknown, b: unknown): void; ok(v: unknown): void; deepEqual(a: unknown, b: unknown): void }
  export default assert
}
declare module "node:test" {
  export function test(name: string, fn: () => void | Promise<void>): void
}
declare module "*.css"
declare namespace JSX {
  interface Element {}
  interface IntrinsicAttributes { key?: string | number }
  type Handler<E> = (event: E) => void
  interface DomProps {
    [prop: string]: any
    onClick?: Handler<MouseEvent & { currentTarget: HTMLElement }>
    onSubmit?: Handler<SubmitEvent & { currentTarget: HTMLFormElement }>
    onChange?: Handler<Event & { target: HTMLInputElement; currentTarget: HTMLInputElement }>
    onKeyDown?: Handler<KeyboardEvent>
  }
  interface IntrinsicElements { [name: string]: DomProps }
}
`

