"use client";

import * as React from "react"

import {
  createLocalShell,
  createWebSocketTransport,
  type ShellCommand,
  type TerminalTransport,
} from "@/registry/base-nova/ui/terminal"

import type { VsCodeHost } from "./host"
import { normalize, rel, ROOT, USER, type Workspace } from "./workspace"

export type TerminalSession = { id: string; title: string; transport: TerminalTransport; remote: boolean }

/** Runs `input` once the first view attaches (after the shell has drawn its prompt). */
function withStartup(t: TerminalTransport, input: string | null): TerminalTransport {
  let sent = !input
  return {
    write: (d) => t.write(d),
    onData(cb) {
      const off = t.onData(cb)
      if (!sent) {
        sent = true
        setTimeout(() => t.write(input!), 0)
      }
      return off
    },
    resize: t.resize ? (c, r) => t.resize!(c, r) : undefined,
    dispose: () => t.dispose?.(),
  }
}

const quote = (s: string) => (/^[\w./~-]+$/.test(s) ? s : `'${s.replace(/'/g, `'\\''`)}'`)

/**
 * Terminal sessions in groups: each group is one tab in the list and shows
 * its terminals side by side (a split). Local sessions run the browser shell
 * on the shared workspace; with a PTY address every new session connects to
 * a real shell instead, and a host's terminal (a desktop shell) wins over both.
 */
export function useTerminals({
  ws,
  ptyUrl,
  host,
  onOpenFile,
}: {
  ws: Workspace
  ptyUrl: string | null
  host?: VsCodeHost
  onOpenFile: (path: string) => void
}) {
  const [sessions, setSessions] = React.useState<TerminalSession[]>([])
  const [groups, setGroups] = React.useState<string[][]>([])
  const [active, setActive] = React.useState<string | null>(null)
  const counter = React.useRef(0)
  const openRef = React.useRef(onOpenFile)
  openRef.current = onOpenFile

  const commands = React.useMemo<Record<string, ShellCommand>>(
    () => ({
      // `code <file…>` opens files in the editor, creating missing ones.
      code: ({ args, cwd, fs, print }) => {
        if (!args.length) {
          print("usage: code <file>…\n")
          return 2
        }
        for (const a of args) {
          const p = normalize(a.startsWith("/") ? a : `${cwd}/${a}`)
          if (fs.isDir(p)) {
            print(`code: ${a}: is a folder\n`)
            continue
          }
          if (!fs.exists(p)) fs.writeFile(p, "")
          openRef.current(p)
        }
        return 0
      },
    }),
    []
  )

  const make = React.useCallback(
    (cwd?: string): TerminalSession => {
      const n = ++counter.current
      if (host?.terminal) {
        const dir = cwd && cwd.startsWith(ROOT) ? rel(cwd) : ""
        const transport = host.terminal({ cwd: ws.mounted ? dir : null, folder: ws.mounted })
        return { id: `term-${n}-${Date.now().toString(36)}`, title: `${host.shellName ?? "shell"} ${n}`, transport, remote: true }
      }
      const remote = !!ptyUrl
      const base = remote ? createWebSocketTransport(ptyUrl!) : createLocalShell({ fs: ws, cwd: ROOT, user: USER, host: "workspace", commands })
      const startup = cwd && cwd !== ROOT ? `cd ${quote(cwd)}\r` : null
      return { id: `term-${n}-${Date.now().toString(36)}`, title: remote ? `bash ${n}` : `sh ${n}`, transport: withStartup(base, startup), remote }
    },
    [ws, ptyUrl, host, commands]
  )

  const create = React.useCallback(
    (cwd?: string) => {
      const s = make(cwd)
      setSessions((list) => [...list, s])
      setGroups((g) => [...g, [s.id]])
      setActive(s.id)
      return s.id
    },
    [make]
  )

  /** Add a terminal next to the active one (up to three side by side). */
  const split = React.useCallback(() => {
    const group = groups.find((g) => active && g.includes(active))
    if (!group) return create()
    if (group.length >= 3) return active
    const s = make()
    setSessions((list) => [...list, s])
    setGroups((gs) => gs.map((g) => (g === group ? [...g, s.id] : g)))
    setActive(s.id)
    return s.id
  }, [groups, active, create, make])

  const kill = React.useCallback(
    (id: string) => {
      const s = sessions.find((x) => x.id === id)
      s?.transport.dispose?.()
      const nextGroups = groups.map((g) => g.filter((x) => x !== id)).filter((g) => g.length)
      setSessions((list) => list.filter((x) => x.id !== id))
      setGroups(nextGroups)
      if (active === id) {
        const flat = nextGroups.flat()
        const old = groups.flat().indexOf(id)
        setActive(flat[Math.min(old, flat.length - 1)] ?? null)
      }
    },
    [sessions, groups, active]
  )

  const rename = React.useCallback((id: string, title: string) => {
    setSessions((list) => list.map((s) => (s.id === id && s.title !== title ? { ...s, title } : s)))
  }, [])

  // Dispose every session when the app unmounts.
  const live = React.useRef(sessions)
  live.current = sessions
  React.useEffect(() => () => live.current.forEach((s) => s.transport.dispose?.()), [])

  const activeGroup = groups.find((g) => active && g.includes(active)) ?? groups[0] ?? []
  return { sessions, groups, active, activeGroup, setActive, create, split, kill, rename }
}

export type Terminals = ReturnType<typeof useTerminals>

import type { ShellFs } from "@/registry/base-nova/ui/terminal"

import type { HostChange, HostFolder, HostFs } from "./host"
import { SEED_DIRS, SEED_FILES } from "./seed"

/** Shell user, home and the folder the explorer shows. */
export const USER = "dev"
export const HOME = `/home/${USER}`
export const ROOT = `${HOME}/tasks-web`
export const ROOT_NAME = "tasks-web"

const STORAGE_KEY = "vscode-template:workspace"
const SYSTEM_DIRS = ["/", "/home", HOME, "/tmp"]

export function normalize(path: string): string {
  const out: string[] = []
  for (const part of path.split("/")) {
    if (!part || part === ".") continue
    if (part === "..") out.pop()
    else out.push(part)
  }
  return `/${out.join("/")}`
}

export function dirname(path: string) {
  const i = path.lastIndexOf("/")
  return i <= 0 ? "/" : path.slice(0, i)
}

export function basename(path: string) {
  return path.slice(path.lastIndexOf("/") + 1)
}

/** Path relative to the workspace root ("" for the root itself). */
export function rel(path: string) {
  return path === ROOT ? "" : path.startsWith(`${ROOT}/`) ? path.slice(ROOT.length + 1) : path
}

export function abs(relative: string) {
  return relative ? normalize(`${ROOT}/${relative}`) : ROOT
}

export function inWorkspace(path: string) {
  return path === ROOT || path.startsWith(`${ROOT}/`)
}

type Saved = { v: 1; files: Record<string, string>; dirs: string[]; baseline: Record<string, string> }

function fsError(code: string, path: string) {
  return Object.assign(new Error(`${code}: ${path}`), { code })
}

/**
 * The workspace file system: one synchronous store shared by the explorer,
 * the editor and every local terminal (it implements the shell's file system
 * interface). Changes under the workspace root persist in localStorage, or,
 * with a folder mounted from disk, are written through to it.
 * `baseline` is the last commit, which source control diffs against.
 */
export class Workspace implements ShellFs {
  private files = new Map<string, string>()
  private dirs = new Set<string>()
  private listeners = new Set<() => void>()
  private pending = false
  private saveTimer: ReturnType<typeof setTimeout> | undefined
  baseline: Record<string, string> = {}
  /** Bumps on every change; a cheap snapshot for useSyncExternalStore. */
  version = 0
  /** Whether the state came from storage rather than the seed. */
  restored = false
  /** Name the explorer shows for the root. */
  name = ROOT_NAME
  private disk: { fs: HostFs; onError: (e: unknown) => void } | null = null
  private applying = false

  constructor() {
    if (!this.load()) this.seed()
  }

  /* ------------------------------ lifecycle ------------------------------- */

  private seed() {
    this.files.clear()
    this.dirs = new Set(SYSTEM_DIRS)
    this.dirs.add(ROOT)
    for (const d of SEED_DIRS) this.mkdir(abs(d))
    for (const [p, content] of Object.entries(SEED_FILES)) this.put(abs(p), content)
    this.baseline = { ...SEED_FILES }
  }

  private load() {
    if (typeof window === "undefined") return false
    try {
      const saved = JSON.parse(localStorage.getItem(STORAGE_KEY) ?? "null") as Saved | null
      if (!saved || saved.v !== 1) return false
      this.dirs = new Set([...SYSTEM_DIRS, ROOT, ...saved.dirs.map(abs)])
      for (const [p, content] of Object.entries(saved.files)) this.put(abs(p), content)
      this.baseline = saved.baseline
      this.restored = true
      return true
    } catch {
      return false
    }
  }

  private persist() {
    if (typeof window === "undefined" || this.disk) return
    clearTimeout(this.saveTimer)
    this.saveTimer = setTimeout(() => {
      const files: Record<string, string> = {}
      for (const [p, c] of this.files) if (inWorkspace(p)) files[rel(p)] = c
      const dirs = [...this.dirs].filter((d) => d !== ROOT && inWorkspace(d)).map(rel)
      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify({ v: 1, files, dirs, baseline: this.baseline } satisfies Saved))
      } catch {
        /* storage full or blocked: keep working in memory */
      }
    }, 150)
  }

  /** Whether the root is a folder on disk. */
  get mounted() {
    return !!this.disk
  }

  /**
   * Show a folder from disk at the root. From here on every change under the
   * root is also written to `fs`; failed writes go to `onError`.
   */
  mount(folder: HostFolder, fs: HostFs, onError: (e: unknown) => void) {
    clearTimeout(this.saveTimer)
    this.files.clear()
    this.dirs = new Set([...SYSTEM_DIRS, ROOT])
    for (const d of folder.dirs) this.ensureDir(abs(d))
    for (const [p, content] of Object.entries(folder.files)) this.put(abs(p), content)
    this.baseline = { ...folder.files }
    this.name = folder.name
    this.restored = false
    this.disk = { fs, onError }
    this.changed()
  }

  /** Back to the in-browser workspace. */
  unmount() {
    if (!this.disk) return
    this.disk = null
    this.name = ROOT_NAME
    this.files.clear()
    if (!this.load()) this.seed()
    this.changed()
  }

  /** Take changes made on disk by something else, without writing them back. */
  applyExternal(changes: HostChange[]) {
    this.applying = true
    try {
      for (const c of changes) {
        const p = abs(c.path)
        try {
          if (c.type === "write") this.writeFile(p, c.content)
          else if (c.type === "mkdir") this.mkdir(p)
          else if (this.exists(p)) this.rm(p, { recursive: true })
        } catch {
          /* a file became a folder or the reverse: the next change settles it */
        }
      }
    } finally {
      this.applying = false
    }
  }

  private write(op: (fs: HostFs) => Promise<void>, ...paths: string[]) {
    const disk = this.disk
    if (!disk || this.applying || !paths.every((p) => p !== ROOT && inWorkspace(p))) return
    op(disk.fs).catch(disk.onError)
  }

  /** Back to the starter project, and forget the saved copy. */
  reset() {
    this.disk = null
    this.name = ROOT_NAME
    this.seed()
    this.restored = false
    this.changed()
  }

  /** Record the current files as the new baseline. */
  commit() {
    this.baseline = Object.fromEntries(this.listFiles().map((p) => [rel(p), this.files.get(p)!]))
    this.changed()
  }

  /** Replace a file's content with its last committed version (or delete it if it is new). */
  discard(path: string) {
    const base = this.baseline[rel(path)]
    if (base === undefined) this.rm(path)
    else this.writeFile(path, base)
  }

  subscribe(cb: () => void) {
    this.listeners.add(cb)
    return () => {
      this.listeners.delete(cb)
    }
  }

  getVersion = () => this.version

  private changed() {
    this.version++
    this.persist()
    // Batch bursts (rm -r, cp -r) into one notification.
    if (this.pending) return
    this.pending = true
    queueMicrotask(() => {
      this.pending = false
      this.listeners.forEach((l) => l())
    })
  }

  /* ------------------------------ file system ------------------------------ */

  private ensureDir(dir: string) {
    let d = dir
    while (!this.dirs.has(d)) {
      this.dirs.add(d)
      d = dirname(d)
    }
  }

  private put(path: string, content: string) {
    this.ensureDir(dirname(path))
    this.files.set(path, content)
  }

  exists(path: string) {
    const p = normalize(path)
    return this.files.has(p) || this.dirs.has(p)
  }

  isDir(path: string) {
    return this.dirs.has(normalize(path))
  }

  readdir(path: string) {
    const p = normalize(path)
    if (!this.dirs.has(p)) throw fsError(this.files.has(p) ? "ENOTDIR" : "ENOENT", p)
    const out: { name: string; dir: boolean }[] = []
    for (const d of this.dirs) if (d !== p && dirname(d) === p) out.push({ name: basename(d), dir: true })
    for (const f of this.files.keys()) if (dirname(f) === p) out.push({ name: basename(f), dir: false })
    return out.sort((a, b) => a.name.localeCompare(b.name))
  }

  readFile(path: string) {
    const p = normalize(path)
    const content = this.files.get(p)
    if (content === undefined) throw fsError(this.dirs.has(p) ? "EISDIR" : "ENOENT", p)
    return content
  }

  writeFile(path: string, content: string) {
    const p = normalize(path)
    if (this.dirs.has(p)) throw fsError("EISDIR", p)
    if (this.files.get(p) === content) return
    this.put(p, content)
    this.write((fs) => fs.writeFile(rel(p), content), p)
    this.changed()
  }

  mkdir(path: string) {
    const p = normalize(path)
    if (this.files.has(p)) throw fsError("EEXIST", p)
    let d = p
    let added = false
    while (!this.dirs.has(d)) {
      this.dirs.add(d)
      added = true
      d = dirname(d)
    }
    if (!added) return
    this.write((fs) => fs.mkdir(rel(p)), p)
    this.changed()
  }

  rm(path: string, opts?: { recursive?: boolean }) {
    const p = normalize(path)
    if (this.files.delete(p)) {
      this.write((fs) => fs.rm(rel(p)), p)
      return this.changed()
    }
    if (!this.dirs.has(p)) throw fsError("ENOENT", p)
    if (p === "/" || p === ROOT) throw fsError("EPERM", p)
    const inside = (x: string) => x.startsWith(`${p}/`)
    const children = [...this.files.keys()].some(inside) || [...this.dirs].some(inside)
    if (children && !opts?.recursive) throw fsError("ENOTEMPTY", p)
    for (const f of [...this.files.keys()]) if (inside(f)) this.files.delete(f)
    for (const d of [...this.dirs]) if (inside(d)) this.dirs.delete(d)
    this.dirs.delete(p)
    this.write((fs) => fs.rm(rel(p)), p)
    this.changed()
  }

  /** Move a file or folder (and everything inside it). */
  rename(from: string, to: string) {
    const a = normalize(from)
    const b = normalize(to)
    if (a === b) return
    if (this.exists(b)) throw fsError("EEXIST", b)
    if (b.startsWith(`${a}/`)) throw fsError("EINVAL", b)
    if (this.files.has(a)) {
      this.put(b, this.files.get(a)!)
      this.files.delete(a)
    } else if (this.dirs.has(a)) {
      const move = (x: string) => b + x.slice(a.length)
      for (const d of [...this.dirs]) if (d === a || d.startsWith(`${a}/`)) {
        this.dirs.delete(d)
        this.dirs.add(move(d))
      }
      for (const [f, c] of [...this.files]) if (f.startsWith(`${a}/`)) {
        this.files.delete(f)
        this.put(move(f), c)
      }
      this.ensureDir(dirname(b))
    } else throw fsError("ENOENT", a)
    this.write((fs) => fs.rename(rel(a), rel(b)), a, b)
    this.changed()
  }

  /* ------------------------------- queries -------------------------------- */

  /** Every file under the workspace root, sorted. */
  listFiles() {
    return [...this.files.keys()].filter((p) => p.startsWith(`${ROOT}/`)).sort()
  }

  /** Every folder under the workspace root (not the root itself), sorted. */
  listDirs() {
    return [...this.dirs].filter((p) => p.startsWith(`${ROOT}/`)).sort()
  }

  /** Files that differ from the baseline: modified, added or deleted (relative paths). */
  changes() {
    const out: { path: string; status: "M" | "A" | "D" }[] = []
    const current = new Set<string>()
    for (const p of this.listFiles()) {
      const r = rel(p)
      current.add(r)
      const base = this.baseline[r]
      if (base === undefined) out.push({ path: r, status: "A" })
      else if (base !== this.files.get(p)) out.push({ path: r, status: "M" })
    }
    for (const r of Object.keys(this.baseline)) if (!current.has(r)) out.push({ path: r, status: "D" })
    return out.sort((a, b) => a.path.localeCompare(b.path))
  }
}

